using Microsoft.AspNetCore.Mvc;
using TrainingAndAssessmentWebAPI.Models;
using TrainingAndAssessmentWebAPI.Services;

namespace TrainingAndAssessmentWebAPI.Controllers;

[ApiController,Route("api/events")]
public sealed class EventsController(EventPortalRepository repo,EventTeamWorkbookService teamWorkbook):ControllerBase
{
    string Token=>Request.Headers.Authorization.ToString().Replace("Bearer ","",StringComparison.OrdinalIgnoreCase).Trim();
    async Task<(string Type,int Id)?> Identity()=>await repo.Auth(Token);
    [HttpGet] public Task<List<object>> Events()=>repo.PublicEvents();
    [HttpGet("mentors")] public Task<List<object>> Mentors()=>repo.Mentors();
    [HttpGet("teams")] public Task<List<object>> Teams()=>repo.PublicTeams();
    [HttpGet("team-summary")] public Task<object> TeamSummary()=>repo.PublicTeamSummary();
    [HttpGet("winning-teams")] public Task<List<object>> WinningTeams()=>repo.WinningTeams();
    [HttpGet("winning-teams/{id:int}/photo")] public async Task<IActionResult> WinningTeamPhoto(int id){var photo=await repo.WinningTeamPhoto(id);return photo is null?NotFound():File(photo.Value.Data,photo.Value.ContentType,photo.Value.Name);}
    [HttpPost("registrations")] public async Task<IActionResult> Register(EventRegistrationRequest x){try{var y=await repo.Register(x);return Ok(new{registrationReference=y.RegistrationReference,teamNumber=y.TeamNumber,password=y.Password,message="Registration completed. Save the Student/Team number and password securely."});}catch(Exception e){return BadRequest(new{message=e.Message});}}
    [HttpPost("team-login")] public async Task<IActionResult> TeamLogin(EventLoginRequest x)=>await repo.Login("Team",x) is{} y?Ok(y):Unauthorized(new{message="Invalid team number or password."});
    [HttpPost("coordinator-login")] public async Task<IActionResult> CoordinatorLogin(EventLoginRequest x)=>await repo.Login("Coordinator",x) is{} y?Ok(y):Unauthorized(new{message="Invalid coordinator credentials."});
    [HttpGet("team/me")] public async Task<IActionResult> Me(){var a=await Identity();return a is {Type:"Team"}?Ok(await repo.Team(a.Value.Id)):Unauthorized();}
    [HttpPut("team/me")] public async Task<IActionResult> Update(TeamParticipationRequest x){var a=await Identity();if(a is not {Type:"Team"})return Unauthorized();if(await repo.IsFrozen(a.Value.Id))return BadRequest(new{message="The coordinator has verified and frozen this record. Further updates are not permitted."});try{await repo.Participation(a.Value.Id,x);return Ok(await repo.Team(a.Value.Id));}catch(Exception e){return BadRequest(new{message=e.Message});}}
    [HttpPut("team/me/details")] public async Task<IActionResult> UpdateDetails(TeamDetailsUpdateRequest x){var a=await Identity();if(a is not {Type:"Team"})return Unauthorized();if(await repo.IsFrozen(a.Value.Id))return BadRequest(new{message="The coordinator has verified and frozen this record. Further updates are not permitted."});try{await repo.UpdateOwnDetails(a.Value.Id,x.Members);return Ok(await repo.Team(a.Value.Id));}catch(Exception e){return BadRequest(new{message=e.Message});}}
    [HttpPost("team/change-password")] public async Task<IActionResult> Change(PasswordChangeRequest x){var a=await Identity();if(a is not {Type:"Team"})return Unauthorized();try{await repo.ChangePassword(a.Value.Id,x.CurrentPassword,x.NewPassword);return Ok();}catch(Exception e){return BadRequest(new{message=e.Message});}}
    [HttpPost("team/files")] public async Task<IActionResult> Upload([FromForm]string fileType,[FromForm]string description,IFormFile file){var a=await Identity();if(a is not {Type:"Team"})return Unauthorized();if(await repo.IsFrozen(a.Value.Id))return BadRequest(new{message="The coordinator has verified and frozen this record. Further uploads are not permitted."});try{return Ok(await repo.SaveFile(a.Value.Id,fileType,description,file));}catch(Exception e){return BadRequest(new{message=e.Message});}}
    [HttpGet("files/{id:guid}")] public async Task<IActionResult> Download(Guid id){var a=await Identity();if(a is null)return Unauthorized();var f=await repo.File(id,a.Value.Id,a.Value.Type=="Coordinator");return f is null?NotFound():File(f.Value.Data,f.Value.ContentType,f.Value.Name);}
    [HttpGet("coordinator/dashboard")] public async Task<IActionResult> Dashboard(){var a=await Identity();return a is {Type:"Coordinator"}?Ok(new{events=await repo.PublicEvents(),teams=await repo.Dashboard(),mentors=await repo.MentorAllocations(),winningTeams=await repo.WinningTeams()}):Unauthorized();}
    [HttpGet("coordinator/team-details.xlsx")] public async Task<IActionResult> TeamDetailsWorkbook(){var a=await Identity();return a is {Type:"Coordinator"}?File(await teamWorkbook.GenerateAsync(),"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",$"Team_Details_CSE_{DateTime.Now:yyyyMMdd}.xlsx"):Unauthorized();}
    [HttpPost("coordinator/winning-teams")] public async Task<IActionResult> AddWinningTeam([FromForm]string socialMediaUrl,IFormFile photo){var a=await Identity();if(a is not {Type:"Coordinator"})return Unauthorized();try{return Ok(await repo.SaveWinningTeam(null,socialMediaUrl,photo));}catch(Exception e){return BadRequest(new{message=e.Message});}}
    [HttpPut("coordinator/winning-teams/{id:int}")] public async Task<IActionResult> EditWinningTeam(int id,[FromForm]string socialMediaUrl,IFormFile? photo){var a=await Identity();if(a is not {Type:"Coordinator"})return Unauthorized();try{return Ok(await repo.SaveWinningTeam(id,socialMediaUrl,photo));}catch(Exception e){return BadRequest(new{message=e.Message});}}
    [HttpDelete("coordinator/winning-teams/{id:int}")] public async Task<IActionResult> DeleteWinningTeam(int id){var a=await Identity();if(a is not {Type:"Coordinator"})return Unauthorized();await repo.DeleteWinningTeam(id);return NoContent();}
    [HttpPost("coordinator/events")] public async Task<IActionResult> AddEvent(ExternalEventRequest x){var a=await Identity();if(a is not {Type:"Coordinator"})return Unauthorized();await repo.SaveEvent(null,x);return Ok();}
    [HttpPut("coordinator/events/{id:int}")] public async Task<IActionResult> EditEvent(int id,ExternalEventRequest x){var a=await Identity();if(a is not {Type:"Coordinator"})return Unauthorized();await repo.SaveEvent(id,x);return Ok();}
    [HttpPost("coordinator/teams/{id:int}/approve")] public async Task<IActionResult> Approve(int id){var a=await Identity();if(a is not {Type:"Coordinator"})return Unauthorized();var credentials=await repo.Approve(id);return Ok(new{teamNumber=credentials.TeamNumber,password=credentials.Password});}
    [HttpPut("coordinator/teams/{id:int}/review")] public async Task<IActionResult> Review(int id,TeamReviewRequest x){var a=await Identity();if(a is not {Type:"Coordinator"})return Unauthorized();await repo.Review(id,x);return Ok();}
    [HttpPut("coordinator/teams/{id:int}")] public async Task<IActionResult> UpdateTeam(int id,CoordinatorTeamUpdateRequest x){var a=await Identity();if(a is not {Type:"Coordinator"})return Unauthorized();try{await repo.UpdateTeam(id,x);return Ok();}catch(Exception e){return BadRequest(new{message=e.Message});}}
    [HttpDelete("coordinator/teams/{id:int}")] public async Task<IActionResult> DeleteTeam(int id){var a=await Identity();if(a is not {Type:"Coordinator"})return Unauthorized();return await repo.DeleteTeam(id)>0?Ok(new{message="Team removed and preserved for recovery."}):NotFound(new{message="Team was not found or was already removed."});}
    [HttpPut("coordinator/teams/{id:int}/post-event")] public async Task<IActionResult> UpdatePostEvent(int id,CoordinatorPostEventUpdateRequest x){var a=await Identity();if(a is not {Type:"Coordinator"})return Unauthorized();try{await repo.CoordinatorPostEvent(id,x);return Ok(await repo.Team(id,true));}catch(Exception e){return BadRequest(new{message=e.Message});}}
    [HttpPost("coordinator/teams/{id:int}/files")] public async Task<IActionResult> CoordinatorUpload(int id,[FromForm]string fileType,[FromForm]string description,IFormFile file){var a=await Identity();if(a is not {Type:"Coordinator"})return Unauthorized();try{await repo.SaveFile(id,fileType,description,file);return Ok(await repo.Team(id,true));}catch(Exception e){return BadRequest(new{message=e.Message});}}
    [HttpPut("coordinator/teams/{id:int}/freeze")] public async Task<IActionResult> FreezeTeam(int id,EventFreezeRequest x){var a=await Identity();if(a is not {Type:"Coordinator"})return Unauthorized();await repo.SetFrozen(id,x.IsFrozen);return Ok();}
}
